-- Transaction Data Store (Relational DB for structured data)
CREATE TABLE transactions (
    transaction_id VARCHAR(255) PRIMARY KEY,
    account_id VARCHAR(255) NOT NULL,
    counterparty_account_id VARCHAR(255),
    amount DECIMAL(18, 2) NOT NULL,
    currency VARCHAR(3) NOT NULL,
    transaction_type VARCHAR(50) NOT NULL,
    timestamp TIMESTAMP WITH TIME ZONE NOT NULL,
    source_system VARCHAR(100),
    metadata JSONB
);

CREATE INDEX idx_transactions_account_id ON transactions (account_id);
CREATE INDEX idx_transactions_timestamp ON transactions (timestamp);

-- Feature Store (Relational DB or specialized feature store)
CREATE TABLE transaction_features (
    feature_id UUID PRIMARY KEY,
    transaction_id VARCHAR(255) REFERENCES transactions(transaction_id),
    account_id VARCHAR(255) NOT NULL,
    feature_name VARCHAR(100) NOT NULL,
    feature_value FLOAT NOT NULL,
    calculation_timestamp TIMESTAMP WITH TIME ZONE NOT NULL
);

CREATE INDEX idx_transaction_features_transaction_id ON transaction_features (transaction_id);
CREATE INDEX idx_transaction_features_account_id ON transaction_features (account_id);
CREATE INDEX idx_transaction_features_name_value ON transaction_features (feature_name, feature_value);

-- Alert Store
CREATE TABLE alerts (
    alert_id UUID PRIMARY KEY,
    transaction_id VARCHAR(255) REFERENCES transactions(transaction_id),
    account_id VARCHAR(255) NOT NULL,
    suspicion_score FLOAT NOT NULL,
    alert_timestamp TIMESTAMP WITH TIME ZONE NOT NULL,
    status VARCHAR(50) DEFAULT 'NEW',
    assigned_to VARCHAR(255),
    case_id VARCHAR(255)
);

CREATE INDEX idx_alerts_transaction_id ON alerts (transaction_id);
CREATE INDEX idx_alerts_account_id ON alerts (account_id);
CREATE INDEX idx_alerts_status ON alerts (status);

